appendix:
 &reftitle.examples;


  Ecco un semplice script PHP di esempio che usa il tokenizer per
  leggere un file PHP, rimuovere tutti i commenti dal sorgente
  e stampare solo il codice vero e proprio.


  Rimozione dei commenti con il tokenizer


<?php
$source = file_get_contents('example.php');
$tokens = token_get_all($source);

foreach ($tokens as $token) {
   if (is_string($token)) {
       // token semplice di un solo carattere
       echo $token;
   } else {
       // token sotto forma di array
       list($id, $text) = $token;

       switch ($id) { 
           case T_COMMENT: 
           case T_DOC_COMMENT:
               // nessuna azione sui commenti
               break;

           default:
               // qualsiasi altro token -> output senza modifiche
               echo $text;
               break;
       }
   }
}
?>
